insert into guides (id,content) values ('dogbone-mount-mk7',$j${"id": "dogbone-mount-mk7", "title": "Dogbone (pendulum) mount", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI · same MQB pendulum design", "category": "Bushings & mounts", "kind": "repair", "heroId": "mk7-dogbone", "variants": {"question": "Insert only, or replace the whole mount?", "hint": "An insert is a poly plug that fills the void in the factory rubber bushing — half an hour, no bolt is fully torqued, and the OE mount stays in the car. A full replacement swaps the whole cast dogbone for a stiffer aftermarket unit — better result over time because the poly-in-rubber trick eventually tears the surrounding rubber apart, but two hours and every bolt comes out.", "options": [{"id": "insert", "label": "Insert only", "when": "Cheapest fix; NVH-conscious; new car"}, {"id": "full", "label": "Full mount replacement", "when": "Tuned car, old mount already tired, or the insert has already been tried"}]}, "glance": {"timeFirst": "30 min (insert) · 2 hr (full)", "timeRepeat": "20 min (insert) · 90 min (full)", "difficulty": 2, "cost": "$40–100 (insert) · $150–250 (full mount + insert combo)", "risk": "Insert is a wrestle to seat · full mount has a stretch bolt (M14, single-use)", "why": "The dogbone is the long cast bracket that runs from the underside of the transmission to the front subframe. Its factory rubber bushing is intentionally soft so the drivetrain can rock a little — great for NVH, less great when the car makes real torque or the rubber has aged. Symptoms: clunk on throttle transitions, especially in first or second at low speed, and a lift-off shudder. Fix is either a poly insert into the factory bushing or a stiffer replacement mount with a firmer bushing built in.", "note": "Loudest brand debate in the Mk7 suspension section: 034 vs BFI. Both work. BFI's Powerflex-cored mounts are the durable answer if you're going to keep the car; 034's Density Line inserts are fine on a stock or lightly tuned car."}, "heroCap": "Dogbone runs front-to-back under the transmission. Two 16 mm bolts hold the transmission bracket; one big 21 mm stretch bolt holds the bushing end to the subframe.", "lifespan": {"title": "When to expect it", "headline": ["OE mount holds up to about 60,000–80,000 miles unmodified; tuned cars kill it much sooner"], "earliest": "Immediately after a torque tune if the mount was already tired", "detail": "Symptom pattern: on-throttle clunk in first or second, especially rolling out of a stop. Lift-off in third and you get a jolt as the drivetrain rocks the other way. Look under the car: cracks in the black rubber bushing at the subframe end are the visible sign.", "factors": ["Aggressive tunes and launches", "Age of the rubber", "Long stop-and-go commutes"], "inspect": ["Have someone rock the drivetrain in gear with the brake on and the car in first, then reverse; watch the dogbone from underneath — a bad mount visibly rotates", "Cracked or squeezed rubber at the subframe end is a give-away"], "confidence": {"level": "community", "n": 3, "note": "Consistent forum accounts across GolfMK7 and VWVortex; no factory service interval."}}, "should": {"yesIf": ["Clunk when you get on or off the throttle", "Tuned car past stage 1", "Old mount visibly cracked at the subframe end", "You just did an insert and it didn't fully fix the clunk"], "codes": [], "notes": [{"text": "An insert fills the two rubber voids without removing the mount. Cheap and quick. Downside: the rubber around the insert eventually deforms from being loaded harder than it was designed for, and the benefit fades over 1–2 years on a tuned car. 034 sells a Density Line insert; BFI sells a Powerflex insert.", "only": ["insert"]}, {"text": "A full replacement uses a cast aftermarket dogbone with a firmer bushing pressed in. BFI's Powerflex Hybrid replaces the whole mount with a Powerflex-cored unit. 034's Density Line mount is 034's own casting with a firmer rubber. Either lasts and cures the clunk.", "only": ["full"]}, "The big center bolt at the subframe is an M14 stretch bolt. It's marked single-use by VW and every DIY that reuses it eventually reports the mount going loose. Buy a new one with the insert/mount.", "Give the drivetrain time to settle. Torque the bolts with the car on the ground so the mount isn't pre-loaded at a strange angle.", {"text": "BFI vs 034 is a real disagreement. See the disagreements section — short version: BFI is Anthony's pick for a tuned Mk7 that will keep the mount; 034 is fine for a stock car and cheaper.", "only": ["full"]}], "confidence": {"level": "high", "n": 4, "note": "034 install PDF, ECS Tuning install PDF (bolts, torques, procedure), VWVortex Mk7 mount threads, and the APR pendulum PDF all describe the same layout."}}, "parts": [{"tier": "aftermarket", "name": "034 Motorsport Density Line dogbone insert", "pn": "034-509-1014", "note": "Slides into the OE bushing; ~30 min install", "price": "$40–55", "links": [], "only": ["insert"]}, {"tier": "aftermarket", "name": "BFI Powerflex dogbone insert", "pn": "BFI Stage 1", "note": "Slightly stiffer than 034; some report longer life", "price": "$50–70", "links": [], "only": ["insert"]}, {"tier": "aftermarket", "name": "BFI Powerflex Hybrid dogbone mount", "pn": "BFI HYB Stage 1 or 2", "note": "Replaces the whole cast mount; Powerflex-cored bushing", "price": "$180–250", "links": [], "only": ["full"]}, {"tier": "aftermarket", "name": "034 Motorsport Density Line dogbone mount", "pn": "034-509-5011", "note": "Full mount replacement; 034's own casting", "price": "$180–230", "links": [], "only": ["full"]}, {"tier": "oe", "name": "Dogbone-to-subframe stretch bolt (M14 × 50)", "pn": "N 91201001", "note": "Single-use, torque-to-yield", "price": "$8–12", "links": []}, {"tier": "oe", "name": "Transmission bracket bolts (×2)", "pn": "factory M10", "note": "Reusable if in good shape", "price": "$4", "links": [], "only": ["full"]}], "aftermarket": [{"name": "BFI Powerflex Hybrid", "note": "The forum favorite for durability. Uses Powerflex bushings pressed into BFI's casting so the poly is properly supported, not just squeezed into old rubber.", "price": "$180–250", "signal": "Durable pick"}, {"name": "034 Motorsport Density Line", "note": "Widely available, well-documented install PDF, quieter of the two. Some report the inserts eating the surrounding rubber over 1–2 years.", "price": "$180–230", "signal": "Common pick"}, {"name": "CTS Turbo, Powerflex direct", "note": "Both fine. Powerflex sells the raw bushing to press into any casting.", "price": "$100–200", "signal": "Also fine"}], "tools": [{"name": "Jack + two stands (front only — dogbone lives under the transmission)"}, {"name": "16 mm socket (transmission bracket bolts)"}, {"name": "21 mm socket (subframe stretch bolt) + breaker bar"}, {"name": "Pry bar (helpful for aligning the full replacement)", "only": ["full"]}, {"name": "Silicone grease or the grease supplied with the insert", "only": ["insert"]}, {"name": "Torque wrench, blue thread-locker (optional but common)"}], "before": ["Level ground, front of the car up on stands. The dogbone lives between the front subframe and the underside of the transmission.", "Remove the plastic belly pan if you have one — usually 8–12 T25 screws.", {"text": "Full mount only: buy a new M14 stretch bolt now. Do not reuse the old one.", "only": ["full"]}, {"text": "Insert only: check the direction the insert goes in. 034's has a shape that only fits one way, but forcing it wrong will tear it.", "only": ["insert"]}], "steps": [{"n": 1, "title": "Find the dogbone", "blocks": [{"t": "text", "b": "Under the car, look between the front subframe (the crossmember below the engine) and the underside of the transmission. The dogbone is the long cast arm connecting them, with a big rubber bushing at the subframe end."}, {"t": "ill", "id": "mk7-dogbone", "cap": "Dogbone runs front-to-back. Two 16 mm bolts to the transmission bracket at one end; one 21 mm stretch bolt through the rubber bushing to the subframe at the other."}]}, {"n": 2, "title": "Insert: crack the subframe bolt loose", "only": ["insert"], "blocks": [{"t": "text", "b": "21 mm on the big center bolt at the subframe. You don't need to remove it — just back it off maybe 5 turns so the mount can move slightly. Loosen the two 16 mm bolts at the transmission bracket a few turns as well; the mount needs a bit of slack to slip the insert in."}]}, {"n": 3, "title": "Insert: slide the poly in", "only": ["insert"], "blocks": [{"t": "text", "b": "Grease the insert (a smear of silicone is enough — the tub included with 034 is the right stuff). Push it into the two rubber voids in the OE bushing, front and back of the subframe pin. A pry bar between the dogbone and the subframe gives you the working space to seat it fully."}, {"t": "note", "b": "If it won't seat, the mount isn't loose enough. Back the transmission bolts off another turn or two and try again. Forcing it through without room tears the insert."}]}, {"n": 4, "title": "Insert: torque back down", "only": ["insert"], "blocks": [{"t": "text", "b": "Lower the car to the ground so the drivetrain sits on the mount naturally, then torque. This matters — torquing in the air pre-loads the bushing at the wrong angle."}, {"t": "torque", "label": "Subframe center bolt (M14 stretch — new)", "nm": 100, "note": "+90° turn", "c": {"level": "medium", "n": 2, "note": "ECS Mk7 install: 130 Nm + 90°. Some Mk7 threads report 100 Nm + 90° for the insert-only case where the OE bolt is being reused briefly. If you replaced the bolt (recommended), use 130 Nm + 90°."}}, {"t": "torque", "label": "Transmission bracket bolts (×2)", "nm": 88, "c": {"level": "high", "n": 2, "note": "88 Nm (65 ft-lbs) per ECS install PDF."}}]}, {"n": 5, "title": "Full mount: unbolt", "only": ["full"], "blocks": [{"t": "text", "b": "21 mm on the subframe center bolt: all the way out and set aside (or in the recycling — you're not reusing it). Two 16 mm bolts on the transmission bracket: out. The dogbone drops down and slides forward out of the subframe slot."}]}, {"n": 6, "title": "Full mount: new mount in", "only": ["full"], "blocks": [{"t": "text", "b": "Slide the new mount up into the subframe slot from the front. Line it up so the transmission bracket bolt holes match; a pry bar helps if the drivetrain has sagged. Start all three bolts by hand — the two 16 mm at the transmission end, and the new M14 stretch bolt at the subframe."}]}, {"n": 7, "title": "Full mount: torque on the ground", "only": ["full"], "blocks": [{"t": "text", "b": "Lower the car so the drivetrain settles on the new mount before final torque. Same reason as the insert case — torquing in the air pre-loads the bushing at an angle it won't sit at normally."}, {"t": "torque", "label": "Subframe center bolt (M14 stretch — NEW)", "nm": 130, "note": "+90° turn", "c": {"level": "high", "n": 2, "note": "130 Nm + 90° per ECS Mk7 install PDF; BFI and 034 install guides call for the same."}}, {"t": "torque", "label": "Transmission bracket bolts (×2)", "nm": 88, "c": {"level": "high", "n": 2, "note": "88 Nm (65 ft-lbs) per ECS."}}]}, {"n": 8, "title": "First drive", "blocks": [{"t": "text", "b": "Expect a small NVH bump — a little more felt through the shifter when idling in gear, especially with an insert. That settles over the first week. Rattles or knocking mean something didn't reach torque or the insert isn't fully seated."}, {"t": "note", "b": "Common gotcha: BFI supplies a small washer with their inserts. If you can hear that washer rattling under load, the insert has crushed and you're due for the full replacement."}]}], "alsoReplace": [{"name": "Subframe locking collars (Deadset)", "why": "Only if the subframe is coming down for other work at the same time; not required for a dogbone job. See the Subframe collars guide."}, {"name": "Upper transmission mount", "why": "Same job pattern — if you're replacing the dogbone because the drivetrain is rocking too much, the upper mount is next in line."}], "check": {"tab": "Diagnosis", "title": "Insert or full mount?", "illId": "mk7-dogbone", "illCap": "The rubber bushing is at the subframe end; the two 16 mm bolts are at the transmission end.", "rows": [{"see": "Small clunk on throttle transitions, otherwise fine", "means": "Bushing has softened; not gone.", "do": "Insert first. Cheaper and quicker."}, {"see": "Big clunk on throttle, visible rubber cracks at the subframe end", "means": "Rubber is torn; insert would sit in a broken housing.", "do": "Full mount replacement."}, {"see": "Insert installed a year ago, clunk has come back", "means": "Insert crushed the surrounding rubber.", "do": "Full mount replacement."}, {"see": "Tuned car (stage 2+), old mount", "means": "Insert may not hold long enough to be worth the labor.", "do": "Full mount, BFI Hybrid or 034 Density Line."}], "c": {"level": "high", "n": 3, "note": "Standard forum guidance; no vendor disputes this triage."}}, "aftercare": ["Re-check torques at 100 miles.", "Small NVH bump for the first week is normal and fades.", "New knock after a month with insert: insert has crushed; time for the full mount."], "disagreements": [{"topic": "034 vs BFI", "pos": "034: 'Density Line' rubber, wide install PDF, quieter. BFI: Powerflex-cored, forum-favorite durability.", "call": "BFI Hybrid for a tuned Mk7 that will keep the mount; 034 for a stock or lightly tuned car where NVH matters more."}, {"topic": "Insert torque with reused OE bolt", "pos": "ECS says 130 Nm + 90° across the board; some threads say 100 Nm + 90° when reusing.", "call": "Use a new bolt and the 130 Nm + 90° spec. The bolt is $10."}, {"topic": "Torque on the ground vs in the air", "pos": "Some shop DIYs torque in the air.", "call": "On the ground. Pre-loading the bushing at the wrong angle shortens its life."}], "sources": ["034 Motorsport Billet + Spherical MQB Dogbone Mount install PDF (034-509-1031)", "ECS Tuning Audi 8V / VW MK7 Dogbone Mount and Bushing Insert install PDF", "APR pendulum mount install (TL100057)", "VWVortex Mk7 dogbone threads (034 vs BFI durability debate)", "GolfMK7 'dogbone insert rattle' thread (BFI washer failure mode)", "ShopDAP Mk7 dogbone bolt listing (M14×50 stretch bolt N91201001)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('front-lca-bushings-mk7',$j${"id": "front-lca-bushings-mk7", "title": "Front control arm bushings", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI", "category": "Bushings & mounts", "kind": "repair", "heroId": "mk7-front-lca-bushings", "variants": {"question": "OE, WALK, or full poly?", "hint": "The front lower control arm has two bushings — a round front pivot bushing and a big voided rear bushing. That rear bushing is the one that always goes first and is where all three options act. OE replaces like-for-like. WALK changes the geometry to reduce nose dive under acceleration. Full poly stiffens both bushings and gives the most feel change.", "options": [{"id": "oe", "label": "OE (whole arm)", "when": "Fix a worn bushing, keep factory feel"}, {"id": "walk", "label": "Whiteline WALK (anti-lift)", "brand": true, "when": "Fix nose dive under power, sharpen turn-in"}, {"id": "poly", "label": "Full poly (SuperPro)", "brand": true, "when": "Firmest feel, most feedback, some NVH trade"}]}, "glance": {"timeFirst": "3 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$120–200 (OE pair) · $180 (WALK) · $250–350 (SuperPro alloy arm pair)", "risk": "Stretch bolts (M12, single-use) · alignment required · poly bushings are unforgiving to align", "why": "On the Mk7 the front lower control arm has two bushings. The forward one is a plain round pivot. The rear one is a large hydraulic bushing with fluid-filled voids, designed for NVH — it's also the one that always goes first, and when it goes it feels like wandering steering, brake dive that goes loose, and a knock on the front over small bumps. The fix is either a new arm (OE, with fresh bushings), Whiteline's WALK bushing (rear position only, changes the geometry to reduce nose dive), or a full poly arm from SuperPro that sharpens both ends.", "note": "For OE: FCP Euro's take is right — a whole new arm is often cheaper than pressing new bushings into the old arm, and comes with a new ball joint. For anything past OE, you're changing how the car handles, not just fixing it."}, "heroCap": "Front LCA: front bushing is a round steel-and-rubber pivot; rear bushing is the big voided hydraulic one that always fails first. WALK replaces just the rear.", "lifespan": {"title": "When to expect it", "headline": ["Rear bushing typically dies at 60,000–100,000 miles; front bushing lasts the life of the arm"], "earliest": "Sooner in salt states, or immediately after curb/pothole strikes", "detail": "Symptom pattern: steering that wanders in the lane, brake nose-dive that feels loose or bouncy at the bottom, and a low-speed knock over small bumps. Torn rubber visible at the rear bushing on inspection.", "factors": ["Salt", "Curbs and hard potholes", "Aggressive lowering", "Age of the rubber (it's a hydraulic bushing, fluid escapes)"], "inspect": ["Rear bushing: pry between the arm and its subframe pocket with the car on stands; visible rubber tearing or fluid staining is a done bushing", "Front bushing: look at the pivot for tears or squeezing"], "confidence": {"level": "community", "n": 3, "note": "Symptom pattern and mileage from VWVortex, Grassroots Motorsports and SuperPro's Mk7 pages."}}, "should": {"yesIf": ["Vague steering with a wandering feel", "Nose dive under braking that feels loose", "Low-speed knock from the front", "Visible tear or fluid leak on the rear bushing", "You're already going in for a full alignment refresh", "You want the sharper handling of poly, and you accept a small NVH bump"], "codes": [], "notes": ["Do both sides. Same age, same wear, and mismatched arms drive strangely.", {"text": "OE: cheapest reliable answer is a new arm with the bushings pressed in from the factory. Lemförder or Meyle HD makes the arm; ECS sells a $60 arm as a set of two. You get a new ball joint as a bonus.", "only": ["oe"]}, {"text": "WALK (Whiteline Anti-Lift Kit, part KCA499) replaces only the rear bushing of the front LCA. It moves the bushing pin slightly lower, changing the geometry so the front doesn't lift as much under acceleration. It doesn't add anti-lift — it removes the built-in anti-lift the factory used to reduce dive. Result on a Mk7: less nose dive, sharper turn-in, small increase in torque steer under hard launches.", "only": ["walk"]}, {"text": "SuperPro sells two versions: the poly bushing kit (SPF4176K, rear bushing only) or a full alloy arm set with poly pre-pressed (ALOY0018K). The alloy arm set adds caster and camber compared to OE. The bushing-only kit needs a press.", "only": ["poly"]}, "Alignment is required in every case. The bolts that hold the arm are torque-to-yield stretch bolts, single-use."], "confidence": {"level": "high", "n": 3, "note": "ECS install PDF, SuperPro Mk7 pages, and the Whiteline WALK product listing all describe the same install approach."}}, "parts": [{"tier": "oe", "name": "Front lower control arm (pair, bushings pressed in)", "pn": "Lemförder or Meyle HD", "note": "Cheaper than pressing new bushings into old arms", "price": "$120–200 pair", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "Whiteline WALK kit", "pn": "KCA499", "note": "Rear bushing of front LCA only; anti-lift geometry", "price": "$180 pair", "links": [], "only": ["walk"]}, {"tier": "aftermarket", "name": "SuperPro poly bushing kit (rear position)", "pn": "SPF4176K", "note": "Needs a press to install into your arm", "price": "$120 pair", "links": [], "only": ["poly"]}, {"tier": "aftermarket", "name": "SuperPro alloy arm set (bushings pre-installed)", "pn": "ALOY0018K", "note": "Bolt-in; adds caster and camber", "price": "$550–650 pair", "links": [], "only": ["poly"]}, {"tier": "oe", "name": "Control arm mounting bolts (M12×80, ×4)", "pn": "N 10 640 501", "note": "Stretch bolts, single-use", "price": "$12", "links": []}, {"tier": "oe", "name": "Control arm shouldered nuts (M12, ×2)", "pn": "N 01 508 16", "note": "Rear bushing bolt nuts", "price": "$6", "links": []}, {"tier": "oe", "name": "Ball joint nuts (M10, ×6 if reusing the ball joint)", "pn": "N 10 332 002", "note": "Only if you're not replacing the ball joint too", "price": "$8", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Required", "price": "$100–150", "links": []}], "aftermarket": [{"name": "Whiteline WALK (KCA499)", "note": "The most-loved handling mod on the Mk7 front end after sway bars. Rear-position bushing only, so you can leave the front pivot alone. Adds a small amount of NVH but changes the whole feel of the front under braking and acceleration.", "price": "$180", "signal": "Sharpest bang for buck", "links": []}, {"name": "SuperPro poly (SPF4176K bushings) or ALOY0018K arm set", "note": "Firmest option. The alloy arm set is the bolt-in path — the bushing-only kit needs a shop press. Adds a real NVH bump on the highway.", "price": "$120–650", "signal": "Firmest feel", "links": []}, {"name": "BFI Solid Rubber", "note": "RS3-style solid rubber, sold as complete arms with new ball joints. Middle ground — firmer than OE, quieter than poly. Good long-life pick.", "price": "$300–400 pair", "signal": "OEM+", "links": []}], "tools": [{"name": "Jack + two stands, 17 mm lug socket"}, {"name": "18 mm socket (M12 control arm bolts)"}, {"name": "16 mm socket (ball joint to control arm nuts, only if separating)"}, {"name": "Torque wrench to at least 100 Nm, angle gauge or paint pen"}, {"name": "Hydraulic press (for pressing bushings; skip if using complete arms)", "only": ["poly"]}, {"name": "Penetrating oil, wire brush"}], "before": ["Level ground, both front wheels off the ground together.", "Soak the two rear bushing bolts and the two front bushing bolts with penetrating oil. These live in the salt zone.", "Buy alignment appointment. Don't drive past the shop before it's aligned."], "steps": [{"n": 1, "title": "Wheels off, orient", "blocks": [{"t": "text", "b": "Both fronts up on stands, wheels off. Look at the arm: two front bushing bolts through the subframe (vertical), one rear bushing bolt through the subframe (horizontal). Plus three nuts holding the ball joint to the arm."}, {"t": "ill", "id": "mk7-front-lca-bushings", "cap": "Front pivot bushing (round, front of arm) and rear voided bushing (large, rear of arm). WALK replaces only the rear."}]}, {"n": 2, "title": "Ball joint from the arm", "blocks": [{"t": "text", "b": "16 mm on the three M10 nuts holding the ball joint to the underside of the arm. Off, ball joint stays with the knuckle."}, {"t": "note", "b": "Only necessary for OE (whole arm) or full poly (alloy arm). WALK-only leaves the ball joint attached; the arm comes down as a unit only enough to swap the rear bushing.", "only": ["oe", "poly"]}]}, {"n": 3, "title": "Front bushing bolts out", "only": ["oe", "poly"], "blocks": [{"t": "text", "b": "Two 18 mm bolts through the subframe from the top, into the front pivot bushing. Both out. These are stretch bolts — new ones on install."}]}, {"n": 4, "title": "Rear bushing bolt out", "blocks": [{"t": "text", "b": "18 mm on the horizontal bolt through the rear bushing. Out. New bolt on install."}, {"t": "text", "b": "Arm drops out (OE/poly), or the rear bushing pin drops (WALK).", "only": ["oe", "poly"]}, {"t": "text", "b": "For WALK: the arm stays in the car. Pull the OE rear bushing out of its bracket — it slides out toward the ground — and slot the WALK bushing in its place. The WALK bracket sits slightly lower than the OE; that's the whole point.", "only": ["walk"]}]}, {"n": 5, "title": "New arm or new bushing in", "blocks": [{"t": "text", "b": "OE / poly: slide the new arm up into position, front bushing first (into the subframe pocket), then swing the rear bushing up into its bracket. Start all four bolts by hand. Don't torque yet.", "only": ["oe", "poly"]}, {"t": "text", "b": "WALK: the new poly bushing seats in the lowered bracket. Grease the poly per the Whiteline instructions. Hand-start the bolt through it.", "only": ["walk"]}]}, {"n": 6, "title": "Ball joint back onto the arm", "only": ["oe", "poly"], "blocks": [{"t": "text", "b": "Three new M10 self-locking nuts on the ball joint studs where they come through the arm. Snug them evenly."}, {"t": "torque", "label": "Ball joint to arm (×3, M10)", "nm": 40, "note": "+45° turn", "c": {"level": "high", "n": 2, "note": "40 Nm + 45° per ECS Mk7 control-arm install PDF."}}]}, {"n": 7, "title": "Torque the bushing bolts", "blocks": [{"t": "text", "b": "Wheels back on to hand-tight. Lower the car so the suspension takes its own weight — this is critical for the rear bushing bolt, which needs to be torqued at ride height so the bushing doesn't sit pre-loaded."}, {"t": "torque", "label": "Control arm bolts (front + rear, M12 stretch, NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 2, "note": "70 Nm + 180° per ECS Mk7 install PDF; 034 install PDF calls for the same on the arm bolts."}}]}, {"n": 8, "title": "Alignment", "blocks": [{"t": "text", "b": "Drive gently to the alignment shop. Toe and camber will be off — WALK deliberately pulls toe out a small amount, and any bushing swap changes the arm's rest position slightly."}]}], "alsoReplace": [{"name": "Ball joints", "why": "On the arm anyway (OE / poly cases). Fresh joints for $60 while you're in there. See the Ball joints guide."}, {"name": "Sway bar end links", "why": "Only if worn; same corner, similar age."}, {"name": "Wheel alignment", "why": "Required."}], "check": {"tab": "Diagnosis", "title": "Which bushing, which route?", "illId": "mk7-front-lca-bushings", "illCap": "Rear bushing dies first. WALK replaces only that one; OE/poly do both.", "rows": [{"see": "Wander, loose brake dive, low-speed knock", "means": "Rear bushing (typical).", "do": "OE whole-arm, WALK, or full poly — see notes."}, {"see": "Play at the front bushing, arm rocks visibly", "means": "Front bushing too (rare).", "do": "OE whole-arm."}, {"see": "Nose dive under acceleration bothers you", "means": "Not really a failure — factory geometry.", "do": "WALK is the specific answer."}, {"see": "Want maximum feel, willing to accept NVH", "means": "Poly.", "do": "SuperPro alloy arm set (ALOY0018K)."}], "c": {"level": "high", "n": 3, "note": "Route selection matches SuperPro's Mk7 catalog description, Whiteline WALK's own product notes, and Grassroots Motorsports project-car write-ups."}}, "aftercare": ["Alignment before highway.", "Re-check torques at 100 miles — bushing bolts need to be at ride height.", "Small NVH bump for the first week, especially with poly. Fades or you get used to it."], "disagreements": [{"topic": "OE whole arm vs pressing bushings", "pos": "FCP: whole arm is cheaper; Pelican: press bushings.", "call": "Whole arm unless you already have a press. Faster and you get a fresh ball joint."}, {"topic": "WALK vs full poly", "pos": "WALK: targeted geometry change. Poly: general stiffness increase.", "call": "They do different things. WALK targets the specific symptom of nose dive; poly firms everything. On a daily driver, WALK gives more benefit per NVH dollar."}, {"topic": "Rear bushing bolt torqued in the air vs at ride height", "pos": "Some DIYs do it in the air.", "call": "Ride height. The bushing sits neutral and lasts longer."}], "sources": ["ECS Tuning MK7 Golf Performance Control Arm Kit install PDF (torques: 70 Nm + 180° arm bolts, 40 Nm + 45° ball joint)", "SuperPro MK7 catalog (ALOY0018K arm, SPF4176K rear bushing kit)", "Whiteline KCA499 (WALK) product listing (rear-position anti-lift bushing)", "VWVortex Mk5/6/7/8 rear-bushings thread (SuperPro, ECS poly, Meyle HD comparison)", "BlackForestIndustries MQB solid rubber control arm listing", "Grassroots Motorsports Mk7 project (WALK feel notes)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('rear-multilink-bushings-mk7',$j${"id": "rear-multilink-bushings-mk7", "title": "Rear multilink bushings", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R multilink · A3/S3 8V multilink · Mk8 GTI", "category": "Bushings & mounts", "kind": "repair", "heroId": "mk7-rear-lca-bushings", "glance": {"timeFirst": "3 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$100–160 (SuperPro pair kit) · + press cost if you don't have one", "risk": "Bolts torqued at ride height · press required · alignment recommended", "why": "The rear multilink has a big lower control arm with two bushings: an inner (at the subframe) and an outer (at the knuckle). Both are voided rubber, and both soften with age — the effect is the back end of the car going a little vague, drifting in fast sweepers, and eventually a knock over bumps. SuperPro sells the poly replacements in two kits: SPF4181K for the inner, SPF4180K for the outer. Getting both makes the back end feel a generation newer.", "note": "Less-loved job than the front bushings because the back doesn't feel as bad when it goes, and because it's a two-person 'lift the arm up' step to get bolts back in. But the transformation on a car past 80k miles is genuine."}, "heroCap": "Rear lower control arm: inner bushing at the subframe (SPF4181K), outer bushing at the knuckle (SPF4180K). Both press-in.", "lifespan": {"title": "When to expect it", "headline": ["Vague at 80,000 miles; noisy at 120,000 miles"], "earliest": "Immediately if the car has been curbed hard or lowered aggressively", "detail": "Rear vagueness that only shows up in fast sweepers, slight rear-steer feeling on rough pavement, then a low knock over speed bumps. Nothing catastrophic — the arm and bushings hold together long past the point where they've stopped locating the wheel precisely.", "factors": ["Age of the rubber", "Aggressive lowering", "Track use", "Salt"], "inspect": ["Pry between the rear LCA and the subframe with the car on stands; visible movement in the inner bushing rubber is done", "Same for the outer at the knuckle"], "confidence": {"level": "community", "n": 3, "note": "Consistent VWVortex accounts; no factory service interval."}}, "should": {"yesIf": ["Rear feels vague in fast sweepers", "Knock from behind over sharp bumps", "Past 80k miles and you want it feeling fresh", "You're already doing rear shocks or coilovers"], "codes": [], "notes": ["Both sides at once, both bushings per side. You will only want to do this job once.", "This is not a curbside job. The rear LCA bolts are torqued at ride height, which means either drive-on ramps under the tires or a two-post lift with wheel dollies.", "SuperPro's DuroBall is a metal-poly hybrid pivot that lasts longer than pure poly and squeaks less. Worth the small premium over generic poly kits.", "Powerflex sells the same style bushings; the install pattern is identical. ECS's poly kit is a third option."], "confidence": {"level": "high", "n": 3, "note": "SuperPro product pages, VWVortex Mk7/Mk8 multilink threads."}}, "parts": [{"tier": "aftermarket", "name": "SuperPro rear LCA inner bushings", "pn": "SPF4181K", "note": "Two bushings, both sides", "price": "$80–110", "links": []}, {"tier": "aftermarket", "name": "SuperPro rear LCA outer bushings", "pn": "SPF4180K", "note": "Two bushings, both sides", "price": "$80–110", "links": []}, {"tier": "oe", "name": "Rear LCA-to-subframe bolts (×2)", "pn": "stretch bolts", "note": "Single-use", "price": "$10", "links": []}, {"tier": "oe", "name": "Rear LCA-to-knuckle bolts (×2)", "pn": "stretch bolts", "note": "Single-use", "price": "$10", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Recommended", "price": "$100–150", "links": []}], "aftermarket": [{"name": "SuperPro DuroBall (SPF4180K + SPF4181K)", "note": "Poly bushings with a metal-poly hybrid design. Wins the durability and squeak-resistance comparisons.", "price": "$160–220", "signal": "Best pick", "links": []}, {"name": "Powerflex", "note": "Standard poly. Cheaper, still good.", "price": "$120–180", "signal": "Budget poly"}, {"name": "ECS poly", "note": "Fine and available; less consistency in fitment reports.", "price": "$100–160", "signal": "Also fine"}], "tools": [{"name": "Ramps (or a lift with wheel dollies) — cannot do on stands"}, {"name": "18 mm and 21 mm sockets, breaker bar"}, {"name": "Hydraulic press for bushing installation", "note": "or take the arms to a machine shop"}, {"name": "Torque wrench, angle gauge, penetrating oil"}], "before": ["Ramps or lift, so the suspension is at ride height throughout.", "Soak all four LCA bolts (two subframe, two knuckle) with penetrating oil the night before.", "Book alignment. Rear toe is adjustable and will move.", "Bushing removal is the fiddly part. If you don't own a press, pull the arms and take them (with the new bushings) to a machine shop; that removes the whole press question."], "steps": [{"n": 1, "title": "Car on ramps, wheels off", "blocks": [{"t": "text", "b": "Drive both rear wheels onto ramps. Chock the fronts. Loosen the lugs, lift each side slightly with a jack so you can pull the wheel, then set back down onto the ramps. The suspension needs to stay at ride height for the whole job."}]}, {"n": 2, "title": "Rear LCA off the knuckle", "blocks": [{"t": "text", "b": "18 mm on the bolt through the outer bushing at the knuckle. Out. Arm swings down at that end."}, {"t": "ill", "id": "mk7-rear-lca-bushings", "cap": "Rear LCA: outer bushing to knuckle, inner bushing to subframe. Both need to come out for the new bushings."}]}, {"n": 3, "title": "Rear LCA off the subframe", "blocks": [{"t": "text", "b": "18 mm (or 21 mm on some) on the inner bushing bolt at the subframe. Out. Arm comes off."}, {"t": "note", "b": "Watch for the eccentric cam washer at the inner bolt — it's the toe adjuster. Mark its position with a paint pen so you can put it back at the same rotation for the drive to the alignment shop."}]}, {"n": 4, "title": "Bushings out, new ones in", "blocks": [{"t": "text", "b": "On the bench with a press: press the old bushings out of the arm, press the new SuperPro bushings in. Grease the poly with the tub supplied. If you're using a machine shop, they do this step for $30–50 per bushing."}, {"t": "note", "b": "Press direction matters. The lip goes toward the visible side; check the SuperPro instruction sheet for orientation."}]}, {"n": 5, "title": "Arm back in — subframe end first", "blocks": [{"t": "text", "b": "Lift the arm into position. Start the inner (subframe) bolt through the new bushing by hand — it may need a bit of alignment persuasion. Don't torque yet. Get the eccentric washer back to its paint mark."}]}, {"n": 6, "title": "Outer end back to the knuckle", "blocks": [{"t": "text", "b": "Lift the outer end of the arm up to meet the knuckle. This is where a helper is useful — the arm is heavy and the geometry only works at ride height. Start the outer bolt by hand."}]}, {"n": 7, "title": "Torque — at ride height", "blocks": [{"t": "text", "b": "With the car sitting on the ramps (suspension loaded), torque both bolts. This is critical — bushings that are torqued unloaded end up pre-stressed and fail early."}, {"t": "torque", "label": "Rear LCA-to-subframe (inner) M12/M14 stretch bolt (NEW)", "nm": 90, "note": "+90° turn", "c": {"level": "medium", "n": 2, "note": "90 Nm + 90° is the common Mk7/8 multilink spec; MyGolfMk7's table doesn't list this line separately, so this is best-known from cross-referencing SuperPro's install sheet with Mk5/6 rear-arm torques."}}, {"t": "torque", "label": "Rear LCA-to-knuckle (outer) M12/M14 stretch bolt (NEW)", "nm": 90, "note": "+90° turn", "c": {"level": "medium", "n": 2, "note": "90 Nm + 90° per SuperPro install literature and cross-references. Flagged."}}]}, {"n": 8, "title": "Wheels on, alignment", "blocks": [{"t": "text", "b": "Wheels back on, 120 Nm lug torque. Drive gently to the alignment shop — toe is the specific thing that will have moved."}]}], "alsoReplace": [{"name": "Rear shocks / coilovers", "why": "Everything is already at ride height on ramps; if the shocks have miles on them, this is the moment."}, {"name": "Rear sway bar end links", "why": "Same corner, similar age."}, {"name": "Rear wheel bearings", "why": "Only if they're already noisy — see that guide."}], "check": {"tab": "Diagnosis", "title": "When to do it", "illId": "mk7-rear-lca-bushings", "rows": [{"see": "Vague back end in fast sweepers", "means": "Inner bushing softened.", "do": "Both bushings per side, both sides."}, {"see": "Knock over bumps from the back", "means": "Bushing rubber torn.", "do": "Same — poly kit."}, {"see": "Car below 60k miles", "means": "Probably not the bushings yet.", "do": "Look at shocks and sway bar links first."}], "c": {"level": "community", "n": 3, "note": "General diagnostic pattern; individual mileage varies."}}, "aftercare": ["Alignment within a day of finishing.", "Rear feels noticeably firmer for the first week — that's the poly settling.", "Any squeak means a bushing wasn't fully greased; dropping the arm and re-greasing is the fix."], "disagreements": [{"topic": "Ride height vs air for bushing bolt torque", "pos": "Some DIYs do it in the air.", "call": "Ride height. Non-negotiable for bushing life."}, {"topic": "Torque values", "pos": "MyGolfMk7 table doesn't list the rear LCA bolts specifically; SuperPro install lit gives 90 Nm + 90°.", "call": "90 Nm + 90°, flagged. If you have a Bentley manual for the Mk7, confirm."}], "sources": ["SuperPro Mk7 rear LCA product listings (SPF4180K outer, SPF4181K inner)", "VWVortex 'REAR bushings & control arm upgrades — Mk5/Mk6/Mk7/Mk8' thread", "GolfMK7 rear multilink threads (bushings replacement experiences)", "MyGolfMk7 torque spec table (cross-reference for M12/M14 stretch bolt patterns)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('subframe-collars-mk7',$j${"id": "subframe-collars-mk7", "title": "Subframe locking collars (Deadset)", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V · Mk8 GTI · same MQB subframe layout", "category": "Bushings & mounts", "kind": "upgrade", "heroId": "mk7-subframe-collars", "glance": {"timeFirst": "3 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$285 (Tyrolsport Deadset Mk7) · $200 (034 collars) · $180 (Racingline)", "risk": "Front subframe drops several inches — plan supports · ARP torque values are what they are (not the factory number) · pairs well with the front sway bar job", "why": "The MQB front subframe attaches to the chassis through steel-and-rubber isolators plus four main bolts, and it can shift a millimeter or two in its bolt holes under hard cornering or over sharp bumps. That shift is what causes the 'clunk on a sloped driveway' and the loose-alignment feel after a hard track day. Locking collars sit inside the bolt holes and lock the subframe positively to the chassis so it can't move — cleaner alignment, no clunk, sharper turn-in.", "note": "Almost the same install as the front sway bar (subframe drops down to reach the bolt heads), so if you're already doing the sway bar this is the moment. Tyrolsport's Deadset is the gold standard; 034 and Racingline sell equivalents."}, "heroCap": "Front subframe: four main bolts to the chassis. Deadset kit adds bronze collars around each bolt and replaces the two forward brackets with billet-aluminum + integral collar units.", "lifespan": {"title": "When to expect it", "headline": ["Not a failure item — a one-time upgrade"], "earliest": "Any time; typically installed with sway bars or when the 'driveway clunk' starts", "detail": "Not a wear item. The subframe won't fall out without collars. But under hard driving, the small shift in the bolt holes throws off alignment progressively and eventually a low-speed clunk emerges — that's when most owners buy the kit.", "factors": ["Track days", "Aggressive cornering", "Bolt torque loss over years"], "inspect": ["Try to visually shift the subframe with a pry bar against the chassis on a lift; any movement is what the kit fixes", "Driveway apron clunk is the classic tell"], "confidence": {"level": "community", "n": 3, "note": "Tyrolsport product pages and long-running MK5/6/7 install threads."}}, "should": {"yesIf": ["'Driveway clunk' when apron entering/exiting", "Front feels vague after a track day", "You're already dropping the subframe for the front sway bar", "You want sharper, more repeatable alignment"], "codes": [], "notes": ["Tyrolsport Mk7 kit ships different from the Mk5/6 kit: two billet-aluminum brackets with integral collars for the two forward positions, six bronze concentric collars for the four main bolts, and eight ARP fasteners total. Instructions come with the kit and supersede any older PDF you find online.", "The two aftermarket ARP bolts get an anti-seize film per Tyrolsport — the coating is included in the kit.", "This is a subframe-drop job, same as the front sway bar. If you're doing both, do them at once and save yourself the second drop. See the Front sway bar guide for the drop-and-support procedure.", "034's Motorsport version is simpler (just the collars, no bracket swap) and cheaper. Racingline sells another equivalent. All three do the same job; Tyrolsport is the most complete kit."], "confidence": {"level": "high", "n": 3, "note": "Tyrolsport install PDF (Mk5/6), Tyrolsport Mk7 product listing, VWVortex Mk7 Deadset thread, GolfMK7 Deadset threads."}}, "parts": [{"tier": "aftermarket", "name": "Tyrolsport Deadset kit (Mk7)", "pn": "TSDSKVW7-1", "note": "Full kit: brackets, collars, ARP hardware", "price": "$285", "links": []}, {"tier": "aftermarket", "name": "034 Motorsport subframe locking collars", "pn": "034-603-Z019", "note": "Collars only, reuse factory brackets", "price": "$180–200", "links": []}, {"tier": "aftermarket", "name": "Racingline subframe collar kit", "pn": "VWR12G7C", "note": "Alternative to 034", "price": "$180", "links": []}], "aftermarket": [{"name": "Tyrolsport Deadset (TSDSKVW7-1)", "note": "The complete answer: billet-aluminum brackets replace the two forward OE steel brackets, six bronze collars for the four main bolts, ARP fasteners throughout. Well-documented, widely installed.", "price": "$285", "signal": "Best pick", "links": []}, {"name": "034 Motorsport", "note": "Collar-only kit; reuses factory brackets. Cheaper, same core benefit (bolt-hole shift eliminated).", "price": "$180–200", "signal": "Budget pick", "links": []}, {"name": "Racingline VWR", "note": "Same idea as 034. Available where Racingline is stocked.", "price": "$180", "signal": "Also fine"}], "tools": [{"name": "Two jacks + four stands, or a lift. Front of the car must be well supported."}, {"name": "18 mm and 21 mm sockets, breaker bar, torque wrench"}, {"name": "13 mm socket (exhaust hangers, sway bar bolts)"}, {"name": "Transmission jack or floor jack + wide board to lower the subframe safely"}, {"name": "Anti-seize (Tyrolsport supplies it)"}], "before": ["Front of the car up on stands — high enough that the subframe can drop about 4 inches without hitting your ramps or the ground.", "Book alignment — the subframe coming out and back in changes alignment.", "If you're doing this with the front sway bar: read the Front sway bar guide first, drop the subframe once, do both."], "steps": [{"n": 1, "title": "Prep — same drop as the sway bar", "blocks": [{"t": "text", "b": "Same subframe-drop routine as the Front sway bar guide. Belly pan off. Front exhaust hangers unbolted (two 13 mm). Dogbone mount bolts loosened. Steering column pinch bolt marked and separated. Sway-bar end links off the strut."}, {"t": "note", "b": "If any of these sounds unfamiliar, work through the Front sway bar guide steps 1–5 first. Same procedure."}]}, {"n": 2, "title": "Support and lower the subframe", "blocks": [{"t": "text", "b": "Transmission jack (or floor jack + board) under the subframe. Snug enough to hold weight."}, {"t": "text", "b": "Loosen the four main subframe bolts evenly — three or four turns each, in a cross pattern. Once loose, lower the subframe slowly with the jack — 4 inches or so is enough to reach the bolt heads and the two forward brackets."}, {"t": "ill", "id": "mk7-subframe-collars", "cap": "Four main subframe bolts (two forward, two rear). Tyrolsport replaces the two forward OE brackets with billet + integral collar; the four bolt holes get bronze concentric collars."}]}, {"n": 3, "title": "Old brackets off (Tyrolsport)", "blocks": [{"t": "text", "b": "For Tyrolsport: unbolt the two forward OE steel brackets from the chassis (they'll drop with the subframe). Set aside. The billet-aluminum replacements will go in their place."}, {"t": "note", "b": "For 034 or Racingline: no bracket swap, just skip to collar install below."}]}, {"n": 4, "title": "Collars in", "blocks": [{"t": "text", "b": "Six bronze concentric collars go into the four main subframe bolt holes (Tyrolsport: two go into the billet bracket bores, four go into the chassis bores; 034: all six go into the chassis or subframe per its instructions). The bronze bull-nose end goes down, guiding the bolt in."}]}, {"n": 5, "title": "Brackets and ARP hardware in (Tyrolsport)", "blocks": [{"t": "text", "b": "For Tyrolsport: bolt the two billet-aluminum brackets to the chassis with the supplied ARP fasteners, light anti-seize. Snug only for now."}]}, {"n": 6, "title": "Raise the subframe back up", "blocks": [{"t": "text", "b": "With the collars seated in the holes, jack the subframe back up slowly. Start each ARP bolt through the collar and into the chassis by hand — the bull-nose collars centre things so it goes together cleanly."}, {"t": "warn", "b": "Do not force a bolt. If it won't start by hand, the collar has moved. Lower the jack an inch, reseat the collar, try again."}]}, {"n": 7, "title": "Torque, then everything else back", "blocks": [{"t": "text", "b": "Cross-pattern torque on the four main subframe bolts (now ARP)."}, {"t": "torque", "label": "Subframe main bolts (ARP, with anti-seize)", "nm": 85, "c": {"level": "varies", "n": 2, "note": "Tyrolsport revised the ARP spec to 85 Nm (approximately 63 ft-lbs) per their support — the chassis threads are the limit, and 90 ft-lbs was the older MK5/6 number. The Mk7 kit uses the revised value; check the printed sheet in the kit for the current number."}}, {"t": "torque", "label": "Front billet bracket to chassis (Tyrolsport)", "nm": 70, "c": {"level": "medium", "n": 2, "note": "70 Nm (roughly 52 ft-lbs) per Tyrolsport MK5/6 install PDF; the Mk7 kit uses similar hardware."}}, {"t": "text", "b": "Reconnect the dogbone (see Dogbone mount guide for torque — 130 Nm + 90° on a new stretch bolt is the correct value if you removed it). Reattach the steering column pinch bolt (30 Nm + 90°). Sway-bar end links back on strut (55 Nm)."}]}, {"n": 8, "title": "Alignment", "blocks": [{"t": "text", "b": "Even with locating collars centering the subframe, alignment shifts slightly whenever the subframe comes off. Get the alignment done before highway driving."}]}], "alsoReplace": [{"name": "Front sway bar (034 25 mm, Neuspeed 25 mm)", "why": "Subframe is down already. If it's on the list, this is the moment."}, {"name": "Front control arm bushings", "why": "Same reason. Access is easy with the subframe down."}, {"name": "Dogbone mount stretch bolt", "why": "You've loosened it; the M14 is single-use if it's come out completely."}], "check": {"tab": "Diagnosis", "title": "Is it time?", "illId": "mk7-subframe-collars", "rows": [{"see": "'Driveway clunk' when apron entering/exiting", "means": "Subframe has shifted in the bolt holes.", "do": "Deadset kit."}, {"see": "Alignment drifts back after a hard track weekend", "means": "Same cause.", "do": "Deadset kit."}, {"see": "Never track the car, no clunk", "means": "Not a priority.", "do": "Skip unless you're already doing the sway bar."}], "c": {"level": "high", "n": 3, "note": "Symptom pattern is consistent across every Deadset install thread."}}, "aftercare": ["Alignment before the highway.", "Re-torque all four main subframe bolts at 100 miles.", "First drive feels tighter and more precise up front — that's the point."], "disagreements": [{"topic": "Torque on the ARP subframe bolts", "pos": "Original Mk5/6 spec: 90 ft-lbs. Tyrolsport revised: 85 Nm (~63 ft-lbs). Two different units and values.", "call": "85 Nm per Tyrolsport's current support answer. Chassis thread limit is the actual constraint, not the ARP bolt strength."}, {"topic": "Tyrolsport vs 034 vs Racingline", "pos": "All three sell collar kits. Tyrolsport adds a bracket swap; 034/Racingline are collar-only.", "call": "Tyrolsport for the complete answer; 034 for the cheaper option that still does the main job."}, {"topic": "Do you need it if you don't track", "pos": "Some owners install prophylactically.", "call": "Skip unless you have a symptom or you're already dropping the subframe for other work."}], "sources": ["Tyrolsport DeadSet Installation Instructions PDF (procedure and torque revisions)", "Tyrolsport product page for Mk7/Mk8 kit (TSDSKVW7-1, kit contents)", "VWVortex 'TYROLSPORT Deadset Rigid Subframe Collar Kit for Mk7 / MQB' thread", "GolfMK7 'Tyrol Deadset kit vs 034 subframe locking collars etc.' thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('camber-plates-mk7',$j${"id": "camber-plates-mk7", "title": "Camber plates / mounts", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R · A3/S3 8V and 8S · Mk8 GTI · same strut top layout across MQB", "category": "Suspension", "kind": "upgrade", "heroId": "mk7-camber-plate", "variants": {"question": "Fixed camber-adding, or adjustable?", "hint": "Fixed mounts (034 Dynamic+) look like OE mounts but the strut hole sits offset, adding a set amount of camber and caster. They stay quiet. Adjustable plates (IE, Vorshlag, Ground Control) use a spherical bearing in a slotted plate — you can dial in exactly the camber you want, but you pay in NVH.", "options": [{"id": "fixed", "label": "034 Dynamic+ (fixed)", "brand": true, "when": "Street car, some track, want the camber without the noise"}, {"id": "adjustable", "label": "Adjustable plates", "when": "Track focus; want to dial camber per event"}]}, "glance": {"timeFirst": "2 hr", "timeRepeat": "90 min", "difficulty": 3, "cost": "$375 (034 Dynamic+) · $500–800 (IE/Vorshlag adjustable)", "risk": "Compressed spring · alignment mandatory · fully torqued top nut requires strut off the car", "why": "Every lowered Mk7 wants more front camber. The stock adjustment range runs out below about a half-inch drop, so past that you're stuck with too little camber, poor turn-in and tire wear on the outside edges. Camber plates solve it. Fixed mounts add a set amount silently; adjustable plates trade some quiet for tunability.", "note": "Same procedure as coilovers up to the strut being out of the car. If you're installing coilovers, install camber plates at the same time — you're already there."}, "heroCap": "Strut top: three M8 mounting bolts through the strut tower into the OE mount (or into the new camber plate). Center M14 nut holds the strut piston to the mount.", "lifespan": {"title": "When to expect it", "headline": ["Not a wear item — a lowered-car upgrade"], "earliest": "Immediately after any drop past coilover minimum settings or aggressive spring choice", "detail": "Not a failure item. Trigger is either the tire wear pattern of a lowered car eating outside edges, or the desire for actual turn-in on a car that's stuck around –0.5° camber front.", "factors": ["How low the car sits", "Alignment shop's ability to find camber at stock adjustment"], "inspect": ["Alignment printout: if front camber is barely negative or positive on a lowered car, you need plates or the 034 RCO ball joint", "Outside-edge tire wear on the fronts"], "confidence": {"level": "high", "n": 3, "note": "Vendor pages match forum reports; well-understood upgrade."}}, "should": {"yesIf": ["Car is lowered past OE", "Front camber is not enough at alignment", "Uneven tire wear on outside edges", "You're installing coilovers this weekend", "You track the car"], "codes": [], "notes": [{"text": "034 Dynamic+ Camber Mounts (~$375 pair) add a fixed +1.4° negative camber and +1° positive caster at the front. They keep the OE-style rubber bushing so NVH is barely different from stock. Bolt-in — same three M8 mounting bolts as the OE mount, same M14 center nut on the strut.", "only": ["fixed"]}, {"text": "Adjustable plates (IE, Vorshlag, Ground Control) use a spherical bearing in a slotted top plate. Camber is set by sliding the bearing along the slot and locking it. Adds real NVH — you'll hear road noise you didn't before. Great for a track car; overkill for a daily.", "only": ["adjustable"]}, "Do both sides. Camber that's uneven side-to-side pulls.", "Alignment is mandatory. The whole point is more camber than OE, and getting it right needs the shop.", "This is a strut-out job. Same procedure as installing coilovers up to the point where the strut is out of the car."], "confidence": {"level": "high", "n": 3, "note": "034 install PDF, Grassroots Motorsports GTI project (chose 034), and IE product listings."}}, "parts": [{"tier": "aftermarket", "name": "034 Dynamic+ Camber Mount pair", "pn": "034-402-1002", "note": "+1.4° camber, +1° caster (fixed)", "price": "$375", "links": [], "only": ["fixed"]}, {"tier": "aftermarket", "name": "IE adjustable camber plates", "pn": "IESUCI1 (may vary)", "note": "Slotted for adjustment; spherical bearing", "price": "$500–650", "links": [], "only": ["adjustable"]}, {"tier": "aftermarket", "name": "Vorshlag CSS camber plates", "pn": "MK7 fitment", "note": "Fully adjustable; standard track-day pick", "price": "$700–800", "links": [], "only": ["adjustable"]}, {"tier": "oe", "name": "Strut top mount bolts (×3 per side)", "pn": "M8 × 25", "note": "Torque-to-yield; single-use", "price": "$4", "links": []}, {"tier": "oe", "name": "Strut piston center nut (M14, per side)", "pn": "factory", "note": "Reusable if in good shape", "price": "$3", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Mandatory", "price": "$100–150", "links": []}], "aftermarket": [{"name": "034 Dynamic+", "note": "Grassroots Motorsports's GTI project chose these specifically for the fixed +1.4° / +1° adjustment without adjustable-plate NVH. Best pick for a daily-plus-track car.", "price": "$375", "signal": "Best all-around", "links": []}, {"name": "IE / Vorshlag / Ground Control (adjustable)", "note": "Dial camber to the event. Vorshlag CSS is the reference track pick. Expect road noise.", "price": "$500–800", "signal": "Track focused"}, {"name": "BFI adjustable", "note": "Available and functionally similar to IE; less common.", "price": "$500–650", "signal": "Alternative"}], "tools": [{"name": "Jack + two stands, 17 mm lug socket"}, {"name": "Spring compressor — internal type that fits between coils (rental at any parts store)", "note": "Do not skip this. A loaded stock spring will hurt you if the top nut comes off first."}, {"name": "18 mm socket (top mount nuts), 21 mm socket (center strut nut), 14 mm triple square (strut-to-knuckle pinch bolt)"}, {"name": "7 mm allen (or T50 Torx) to hold the strut piston shaft"}, {"name": "Torque wrench, angle gauge, breaker bar"}], "before": ["Level ground, wheels on the ground, loosen lugs.", "Jack the front, stands under the body, wheels off.", "Book alignment for the same day if possible."], "steps": [{"n": 1, "title": "Strut off the car", "blocks": [{"t": "text", "b": "14 mm triple-square + 18 mm nut on the strut-to-knuckle pinch bolt. Out. The knuckle drops away from the strut. Sway-bar end link off the strut (18 mm nut, 5 mm allen to counter-hold)."}, {"t": "text", "b": "Under the hood, three 18 mm nuts on top of the strut tower hold the strut in. Support the strut from below with one hand, undo the three nuts, lower the strut out of the tower."}, {"t": "ill", "id": "mk7-camber-plate", "cap": "Strut top: three M8 nuts through the tower into the mount, one M14 nut in the center holding the strut piston to the mount."}]}, {"n": 2, "title": "Spring compressed, top nut off", "caution": true, "blocks": [{"t": "text", "b": "Strut on the bench. Fit the spring compressor around the spring — not on the strut body — and compress the spring evenly on both sides until the top mount is unloaded (the mount can spin by hand)."}, {"t": "warn", "b": "Never remove the top center nut with the spring loaded. Confirm the mount spins freely first."}, {"t": "text", "b": "21 mm on the center M14 nut, 7 mm allen (or T50 Torx) in the top of the piston to counter-hold. Nut off. Lift the old top mount off."}]}, {"n": 3, "title": "New camber plate on", "blocks": [{"t": "text", "b": "Fit the new plate over the strut piston. For fixed 034: same orientation as the OE mount — the arrow on the plate points forward.", "only": ["fixed"]}, {"t": "text", "b": "For adjustable: preset the plate to roughly the camber you want (usually centered for install, then dial at alignment).", "only": ["adjustable"]}, {"t": "text", "b": "Start the center nut by hand a few threads."}]}, {"n": 4, "title": "Torque the center nut, decompress", "blocks": [{"t": "text", "b": "21 mm on the center nut, counter-hold with the allen. Torque before decompressing the spring."}, {"t": "torque", "label": "Strut piston center nut (M14)", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm per MyGolfMk7 (front strut top lock nut) and GolfMK7 install reference thread."}}, {"t": "text", "b": "Now decompress the spring evenly. The plate should hold the top of the spring; check it seats in the spring perch cleanly."}]}, {"n": 5, "title": "Strut back into the car", "blocks": [{"t": "text", "b": "Lift the assembled strut back up through the tower from below. Start the three M8 bolts through the tower into the plate by hand. New bolts."}, {"t": "torque", "label": "Strut top mount bolts (×3, M8, NEW)", "nm": 15, "note": "+90° turn", "c": {"level": "high", "n": 3, "note": "15 Nm + 90° per MyGolfMk7 (front strut mount bolts), GolfMK7 install reference, DAP install kit."}}]}, {"n": 6, "title": "Strut back to the knuckle", "blocks": [{"t": "text", "b": "Pull the knuckle up over the strut, line up the pinch bolt hole. New pinch bolt (single-use)."}, {"t": "torque", "label": "Strut-to-knuckle pinch bolt (M14, NEW)", "nm": 70, "note": "+180° turn", "c": {"level": "high", "n": 3, "note": "70 Nm + 180° per MyGolfMk7 and GolfMK7 spring/damper reference."}}, {"t": "torque", "label": "Sway-bar end link to strut", "nm": 55, "c": {"level": "high", "n": 2, "note": "55 Nm per MyGolfMk7 (sway bar drop link to knuckle)."}}]}, {"n": 7, "title": "Other side, then alignment", "blocks": [{"t": "text", "b": "Repeat everything on the other side. Wheels on to 120 Nm. Drive gently to the alignment shop — the whole point is more camber, and the shop dials it in properly."}]}], "alsoReplace": [{"name": "Strut top bearings", "why": "Off already. VW updated part is 5Q0-412-249-F. $40 for the pair, do them while the strut is apart."}, {"name": "Coilovers", "why": "Same job path; if coilovers are on the list, install both at once."}], "check": {"tab": "Diagnosis", "title": "When to install", "illId": "mk7-camber-plate", "rows": [{"see": "Alignment printout shows front camber near zero on a lowered car", "means": "Adjustment range exhausted.", "do": "Camber plates or the 034 RCO ball joint (see Ball joints)."}, {"see": "Fronts wearing outside edges", "means": "Not enough camber for the load in corners.", "do": "Camber plates."}, {"see": "Not lowered, stock alignment", "means": "Not needed.", "do": "Skip."}], "c": {"level": "high", "n": 3, "note": "Standard alignment triage."}}, "aftercare": ["Alignment before the highway.", "Re-check the strut top bolts at 100 miles.", "Adjustable plates: expect road noise. Fixed plates: NVH should be indistinguishable from stock."], "disagreements": [{"topic": "Fixed vs adjustable", "pos": "034 (fixed): quiet, adds a set amount. Vorshlag/IE (adjustable): tunable, adds noise.", "call": "Fixed for a daily driver that also tracks; adjustable for a dedicated track car."}, {"topic": "How much camber is enough", "pos": "Street: –1° to –1.5° works. Track: –2° to –3°.", "call": "Depends on tire and driving style. Get the shop's read on your specific tire."}], "sources": ["034 Dynamic+ Camber Mount product listing and Grassroots Motorsports Mk7 GTI project write-up", "MyGolfMk7 torque spec table (strut top bolts, strut piston nut, pinch bolt)", "GolfMK7 'Spring & Shock/Damper Installation Reference Guide'", "DAP install kit torque list", "IE / Vorshlag adjustable plate listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now(), created_at=now();
insert into guides (id,content) values ('rear-camber-toe-arms-mk7',$j${"id": "rear-camber-toe-arms-mk7", "title": "Rear camber & toe arms (adjustable)", "fits": "2015–2021 VW GTI · 2.0T TSI Gen 3 (MQB)", "alsoFits": "Mk7/7.5 GTI and Golf R multilink · A3/S3 8V multilink", "category": "Suspension", "kind": "upgrade", "heroId": "mk7-rear-arms", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$300–400 (034 toe link pair) · $500–700 (full adjustable rear arms — camber + toe)", "risk": "Alignment mandatory · torque at ride height · reference-mark the eccentric cams before removal", "why": "Once the car is lowered past a modest drop, the factory rear camber adjustment (an eccentric bolt on the inner LCA) runs out and you're stuck with excess negative camber and toe you can't dial back. Adjustable rear arms give the shop room to work — you can set camber and toe to whatever you want, not whatever the OE adjustment happens to reach.", "note": "Two-piece decision: the toe link (SuperPro, Whiteline, 034 all sell adjustable toe links) is what most people replace first because rear toe is what actually eats tires. Camber arms are the second half if the toe replacement uses up its own adjustment fixing camber."}, "heroCap": "Rear multilink: toe link (upper trailing rod) and camber arms (upper laterals). Both replace the OE fixed-length arms with turnbuckle-style adjustable versions.", "lifespan": {"title": "When to expect it", "headline": ["Not wear items — a lowered-car upgrade"], "earliest": "Any lowering past a modest drop; often first fitted at the coilover install", "detail": "OE eccentric adjustment at the rear runs out around a 1-inch drop. Past that, you can't get toe or camber back to spec without adjustable arms.", "factors": ["How low the car sits", "Kind of driving (daily eats tires; track wants specific numbers)"], "inspect": ["Alignment printout: numbers in red or with a note about running out of adjustment", "Rear tires wearing inside edges = too much negative camber; feathered wear = toe out of spec"], "confidence": {"level": "high", "n": 3, "note": "Vendor pages, alignment-shop guidance."}}, "should": {"yesIf": ["Alignment shop said they ran out of rear adjustment", "Rear tires wearing inside edges", "You're going to track the car", "You just installed coilovers and want to set proper geometry"], "codes": [], "notes": ["Toe link first. Rear toe drives tire wear more than camber does on a road car; adjustable toe links are cheaper and cover the more common problem.", "Camber arms next if needed. If the toe link alone doesn't get things right, add adjustable camber arms.", "Both sides at once, always. Asymmetric rear adjustment pulls under braking.", "Ride height matters for the final torque. Everything torqued at ride height, not in the air.", "034's Density Line rear toe link (034-407-1000) is the reference part; SuperPro and Whiteline sell equivalents. Same install pattern for all."], "confidence": {"level": "high", "n": 3, "note": "034 install PDF, SuperPro Mk7 catalog, Whiteline product pages."}}, "parts": [{"tier": "aftermarket", "name": "034 Density Line adjustable rear toe link (pair)", "pn": "034-407-1000", "note": "Reference part; 034's own install PDF", "price": "$300–350", "links": []}, {"tier": "aftermarket", "name": "SuperPro adjustable rear toe / camber arms", "pn": "varies (SPF-series)", "note": "Similar functionality", "price": "$300–500", "links": []}, {"tier": "aftermarket", "name": "Whiteline adjustable rear arms", "pn": "KTA-series", "note": "Available, well-documented", "price": "$300–500", "links": []}, {"tier": "oe", "name": "Rear arm mounting bolts (stretch)", "pn": "factory", "note": "Single-use; usually included in the aftermarket kit", "price": "$8", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Mandatory", "price": "$100–150", "links": []}], "aftermarket": [{"name": "034 Motorsport Density Line (034-407-1000)", "note": "Toe link pair. Density Line rubber bushings — quieter than pure poly, still tighter than OE. Well-documented install.", "price": "$300–350", "signal": "Reference pick", "links": []}, {"name": "SuperPro", "note": "Full rear-arm sets available. Similar quality, sometimes more available depending on your region.", "price": "$300–500", "signal": "Also good"}, {"name": "Whiteline", "note": "Turnbuckle-style adjusters, standard aftermarket approach.", "price": "$300–500", "signal": "Also good"}], "tools": [{"name": "Ramps (or lift with wheel dollies) — final torque is at ride height"}, {"name": "18 mm and 21 mm sockets, breaker bar"}, {"name": "Wrench that fits the arm's adjuster flats (varies by brand — usually 24 mm or 27 mm)"}, {"name": "Torque wrench, angle gauge, paint pen"}], "before": ["Ramps out. This is a ride-height job.", "Wheels off (jack each side just enough to pull the wheel, then back down onto ramps).", "Paint-pen mark on the eccentric cam and reference plate at each existing arm position — that gives you a starting point for reassembly.", "Book alignment."], "steps": [{"n": 1, "title": "Measure or mark", "blocks": [{"t": "text", "b": "For each arm you're replacing: measure the OE arm's total length center-to-center, or better, measure the exposed thread at each end. This is your rough starting length for the new arm — set it before installing so you can drive to the shop without eating tires."}]}, {"n": 2, "title": "Old arm out", "blocks": [{"t": "text", "b": "18 mm on the inner bolt (subframe side), 18 mm on the outer bolt (knuckle side). Note the eccentric cam position at the inner if it's the camber arm — that's the OE toe/camber adjustment. Bolts out, arm out."}, {"t": "ill", "id": "mk7-rear-arms", "cap": "Rear multilink: toe link (top rear-facing rod), camber arms (upper laterals). Adjustable versions swap in with new stretch bolts."}]}, {"n": 3, "title": "Preset the new arm", "blocks": [{"t": "text", "b": "Rotate the adjuster (turnbuckle style) so the new arm matches t